<?php session_start();if(!isset($_SESSION["employee_id"])){header("Location: login.php");exit;}include "db.php";$s=$conn->prepare("SELECT SUM(status='Pending') p,SUM(status='Approved') a,SUM(status='Rejected') r FROM leave_applications WHERE employee_id=?");$s->bind_param("i",$_SESSION["employee_id"]);$s->execute();$x=$s->get_result()->fetch_assoc();?>
